RESET ROLE;
DO $$ DECLARE actual jsonb; BEGIN SELECT jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',(SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(coalesce(c.relacl,acldefault('S',c.relowner))) v),'type',format_type(s.seqtypid,NULL),'ownership',(SELECT coalesce(jsonb_agg(jsonb_build_object('column',a.attname,'deptype',d.deptype,'relation',d.refobjid::regclass::text) ORDER BY d.refobjid::regclass::text,a.attname),'[]'::jsonb) FROM pg_depend d JOIN pg_attribute a ON a.attrelid=d.refobjid AND a.attnum=d.refobjsubid WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.refclassid='pg_class'::regclass AND d.deptype IN ('a','i'))) INTO actual FROM pg_class c JOIN pg_sequence s ON s.seqrelid=c.oid WHERE c.oid='public.tournament_obligation_events_event_id_seq'::regclass; IF actual IS DISTINCT FROM '{"owner": "postgres", "acl": ["anon=rwU/postgres", "authenticated=rwU/postgres", "postgres=rwU/postgres", "service_role=rwU/postgres"], "type": "bigint", "ownership": [{"column": "event_id", "relation": "tournament_obligation_events", "deptype": "i"}]}'::jsonb THEN RAISE EXCEPTION 'ARCHIVE_PROVIDER_SEQUENCE_AUTHORITY_CHANGED: public.tournament_obligation_events_event_id_seq' USING DETAIL=actual::text; END IF; END $$;
COMMIT;
